INSERT INTO classes (id, name, description, hit_die, primary_ability, skill_choices, starting_equipment, equipment_choices, display_order, weapon_proficiencies, armor_proficiencies, item_proficiencies) VALUES ('rogue', 'Rogue', 'A scoundrel who uses stealth and trickery to overcome obstacles.', 8, 'Dexterity', 4, '{"armor": "leather_armor", "weapons": ["rapier", "shortbow"], "equipment": ["burglar_pack", "thieves_tools"]}', '[{"name": "Starting Equipment", "options": ["(A) Leather Armor, 2 Daggers, Shortsword, Shortbow, 20 Arrows, Quiver, Thieves Tools, Burglar Pack, 8 GP", "(B) Studded Leather Armor, 2 Shortswords, Thieves Tools, Burglar Pack, 15 GP", "(C) 100 GP"]}]', 4, 'simple weapons,hand crossbow,longsword,rapier,shortsword', 'light armor', '');
