INSERT INTO races (id, name, description, size, speed, ability_score_increases, traits, languages, subraces, display_order) VALUES ('human', 'Human', 'Versatile and ambitious, humans are the most common race in most D&D worlds.', 'Medium', 30, '{}', '{"resourceful": "You gain Heroic Inspiration whenever you finish a Long Rest.", "skillful": "You gain proficiency in one skill of your choice.", "versatile": "You gain an Origin feat of your choice."}', '["Common"]', '[]', 0);
INSERT INTO races (id, name, description, size, speed, ability_score_increases, traits, languages, subraces, display_order) VALUES ('dwarf', 'Dwarf', 'Bold and hardy, dwarves are known as skilled warriors, miners, and workers of stone and metal.', 'Medium', 25, '{}', '{"darkvision": "You have Darkvision with a range of 120 feet.", "dwarven_resilience": "You have Resistance to Poison damage. You also have Advantage on saving throws you make to avoid or end the Poisoned condition.", "dwarven_toughness": "Your Hit Point maximum increases by 1, and it increases by 1 again whenever you gain a level."}', '["Common", "Dwarvish"]', '[]', 1);
