INSERT INTO feats (id, name, description, prerequisites, ability_score_increases, benefits, source, category) VALUES ('musician', 'Musician', 'You gain the following benefits: Instrument Training - You gain proficiency with three Musical Instruments of your choice. Encouraging Song - As you finish a Short or Long Rest, you can play a song on a Musical Instrument with which you have proficiency and give Heroic Inspiration to allies who hear the song. The number of allies you can affect in this way equals your Proficiency Bonus.', '[]', '{}', '{}', 'SRD', 'O');
