INSERT INTO feats (id, name, description, prerequisites, ability_score_increases, benefits, source, category) VALUES ('protection', 'Protection', 'When a creature you can see attacks a target other than you that is within 5 feet of you, you can use your reaction to impose disadvantage on the attack roll. You must be wielding a shield.', '[{"class": {"fighter": 1}}, {"class": {"paladin": 2}}]', '{}', '{}', 'SRD', 'fighting_style');
INSERT INTO feats (id, name, description, prerequisites, ability_score_increases, benefits, source, category) VALUES ('savage_attacker', 'Savage Attacker', 'You''ve trained to deal particularly damaging strikes. Once per turn when you hit a target with a weapon, you can roll the weapon''s damage dice twice and use either roll against the target.', '[]', '{}', '{}', 'SRD', 'O');
