INSERT INTO feats (id, name, description, prerequisites, ability_score_increases, benefits, source, category) VALUES ('tavern_brawler', 'Tavern Brawler', 'You gain the following benefits: Enhanced Unarmed Strike - When you hit with your Unarmed Strike and deal damage, you can deal Bludgeoning damage equal to 1d4 plus your Strength modifier instead of the normal damage of an Unarmed Strike. Damage Rerolls - Whenever you roll a damage die for your Unarmed Strike, you can reroll the die if it rolls a 1, and you must use the new roll.', '[]', '{}', '{}', 'SRD', 'O');
INSERT INTO feats (id, name, description, prerequisites, ability_score_increases, benefits, source, category) VALUES ('thrown_weapon_fighting', 'Thrown Weapon Fighting', 'You can draw a weapon that has the thrown property as part of the attack you make with the weapon. In addition, when you hit with a ranged attack using a thrown weapon, you gain a +2 bonus to the damage roll.', '[{"class": {"fighter": 1}}, {"class": {"paladin": 2}}]', '{}', '{}', 'SRD', 'fighting_style');
INSERT INTO feats (id, name, description, prerequisites, ability_score_increases, benefits, source, category) VALUES ('tough', 'Tough', 'Your Hit Point maximum increases by an amount equal to twice your character level when you gain this feat. Whenever you gain a character level thereafter, your Hit Point maximum increases by an additional 2 Hit Points.', '[]', '{}', '{}', 'SRD', 'O');
INSERT INTO feats (id, name, description, prerequisites, ability_score_increases, benefits, source, category) VALUES ('two-weapon_fighting', 'Two-Weapon Fighting', 'When you engage in two-weapon fighting, you can add your ability modifier to the damage of the second attack.', '[{"class": {"fighter": 1}}, {"class": {"paladin": 2}}]', '{}', '{}', 'SRD', 'fighting_style');
